    # Find the longest non-increasing suffix
    n = len(nums)
    if n <= 1:
        return nums[:]  # single element or empty stays same (sorted)
    # Find pivot index i such that nums[i] < nums[i+1] from right
    i = n - 2
    while i >= 0 and nums[i] >= nums[i+1]:
        i -= 1
    if i == -1:
        # nums are in descending order, return sorted ascending
        return sorted(nums)
    # Find rightmost element greater than nums[i]
    j = n - 1
    while nums[j] <= nums[i]:
        j -= 1
    # Swap pivot with that element
    nums = list(nums)  # make a copy to avoid mutating input
    nums[i], nums[j] = nums[j], nums[i]
    # Reverse suffix i+1:
    nums[i+1:] = reversed(nums[i+1:])
    return nums
