    tokens: list of strings, each either an integer or an operator '+', '-', '*', '/'.
    Returns the integer result with division truncating toward zero.
    """
    if not tokens:
        raise ValueError("Empty token list")
    stack = []
    ops = {
        '+': lambda a, b: a + b,
        '-': lambda a, b: a - b,
        '*': lambda a, b: a * b,
        '/': lambda a, b: int(a / b)  # truncates toward zero
    }
    for token in tokens:
        if token in ops:
            if len(stack) < 2:
                raise ValueError("Insufficient operands for operator")
            b = stack.pop()
            a = stack.pop()
            result = ops[token](a, b)
            stack.append(result)
        else:
            # token should be an integer literal, possibly with sign
            try:
                stack.append(int(token))
            except ValueError:
                raise ValueError(f"Invalid token: {token}")
    if len(stack) != 1:
        raise ValueError("Invalid RPN expression")
    return stack[0]

