def solve(s):
    """Return a list of [character, count] pairs for each run of equal characters, in order.

    Example: solve('aab') == [['a', 2], ['b', 1]]
    Handles None (returns []) and any iterable of characters.
    """
    out = []
    if s is None:
        return out
    for ch in s:
        if out and out[-1][0] == ch:
            out[-1][1] += 1
        else:
            out.append([ch, 1])
    return out

def solve(n, b):
    if n == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    sign = '-' if n < 0 else ''
    n = abs(n)
    out = []
    while n > 0:
        out.append(digits[n % b])
        n //= b
    return sign + ''.join(reversed(out))

