def solve(coins, amount):
    best = [0] + [None] * amount
    for v in range(1, amount + 1):
        opts = [best[v - c] for c in coins if c <= v and best[v - c] is not None]
        best[v] = min(opts) + 1 if opts else None
    return -1 if best[amount] is None else best[amount]

def solve(w, k):
    c = {}
    for x in w:
        c[x] = c.get(x, 0) + 1
    return sorted(c, key=lambda x: (-c[x], x))[:k]

def solve(n):
    """Return the number of primes strictly less than n.
    Uses the Sieve of Eratosthenes with O(n log log n) time.
    """
    if n <= 2:
        return 0
    limit = n - 1
    sieve = bytearray(b'\x01') * (limit + 1)
    sieve[0:2] = b'\x00\x00'
    import math
    for p in range(2, int(math.isqrt(limit)) + 1):
        if sieve[p]:
            start = p * p
            step = p
            sieve[start:limit+1:step] = b'\x00' * ((limit - start) // step + 1)
    return sum(sieve)

