def solve(s):
    """Return True if brackets in s are balanced and properly nested.
    Supports (), [], {}. Ignores any other characters.
    Handles non-string inputs gracefully by returning False.
    """
    if not isinstance(s, (str, bytes)):
        return False
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())
    stack = []
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack

