def solve(path):
    """Simplify an absolute Unix path.
    Handles strings and bytes; resolves '.' and '..', collapses multiple slashes,
    and removes any trailing slash (except root remains '/').
    """
    # Normalise bytes to string
    if isinstance(path, bytes):
        try:
            path = path.decode()
        except Exception:
            return '/'  # cannot decode, treat as root
    # Must be a string and start with '/'
    if not isinstance(path, str) or not path.startswith('/'):
        return '/'  # per spec, input should be absolute; fallback to root
    parts = path.split('/')
    stack = []
    for part in parts:
        if not part or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            # if stack empty, stay at root
        else:
            stack.append(part)
    return '/' + '/'.join(stack) if stack else '/'

