def solve(intervals):
    # Handle empty input
    if not intervals:
        return []
    # Normalize intervals to [start, end] as integers, ignore malformed entries
    norm = []
    for iv in intervals:
        if not isinstance(iv, (list, tuple)) or len(iv) < 2:
            continue
        try:
            s, e = iv[0], iv[1]
        except Exception:
            continue
        # ensure numeric types
        try:
            _ = s + e
        except Exception:
            continue
        if s > e:
            s, e = e, s
        norm.append([s, e])
    if not norm:
        return []
    norm.sort(key=lambda x: (x[0], x[1]))
    merged = []
    cur_start, cur_end = norm[0]
    for start, end in norm[1:]:
        if start <= cur_end:  # overlap or touch
            cur_end = max(cur_end, end)
        else:
            merged.append([cur_start, cur_end])
            cur_start, cur_end = start, end
    merged.append([cur_start, cur_end])
    return merged

