def solve(grid):
    """Return the number of islands in a binary grid.
    An island is a group of horizontally or vertically adjacent cells with value 1.
    Empty grid returns 0.
    """
    if not grid:
        return 0
    m = len(grid)
    n = len(grid[0]) if m else 0
    visited = [[False]*n for _ in range(m)]
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            # explore neighbors
            if x > 0 and grid[x-1][y] == 1 and not visited[x-1][y]:
                stack.append((x-1, y))
            if x < m-1 and grid[x+1][y] == 1 and not visited[x+1][y]:
                stack.append((x+1, y))
            if y > 0 and grid[x][y-1] == 1 and not visited[x][y-1]:
                stack.append((x, y-1))
            if y < n-1 and grid[x][y+1] == 1 and not visited[x][y+1]:
                stack.append((x, y+1))
    count = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1 and not visited[i][j]:
                count += 1
                dfs(i, j)
    return count

