def solve(nums):
    import bisect
    tails = []  # tails[i] = smallest possible tail of an increasing subseq of length i+1
    for x in nums:
        # find insertion point
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

